/* Gefahren aus Storm and Root (S. 170–185): Krankheiten und Leviathane. Teil b2. Muss nach gefahren-bilder.js (GIMG) geladen werden. */
window.WS_GEFAHR = window.WS_GEFAHR || [];
if(window.GIMG){ GIMG["sirenruf"] = [755, 980]; GIMG["mangrove"] = [1199, 1067]; GIMG["monument-potoo"] = [1400, 592]; }
WS_GEFAHR.push(
/* ===== Krankheiten (S. 170–173, 179) ===== */
{id:"sr-krankheiten", t:"Krankheiten in Höhe und Tiefe", en:"Illnesses", kat:"krankheiten", p:170, q:"sr", kurz:true,
 x:"In der Tiefe mehr Gefahr als in den Himmeln; die meisten Krankheiten sind eher ein bleibendes Ärgernis als eine echte Bedrohung … Doch die Annahme einer harmlosen Natur hat schon mehr als einen vielversprechenden Wildsegler das Leben gekostet.",
 extra:[["Hohe Krankheiten im Spiel","Die Sternenkrankheit ist die berühmteste Krankheit, die einzigartig für das Wilde Blau ist, und zumindest ein Teil dieser Berühmtheit rührt vom Mangel an Konkurrenz her. Die Himmel gehören zu den sichersten Orten der Wildsee, was Infektionen und Parasiten angeht, denn die weiten offenen Räume verringern die Gelegenheiten für Aeronauten, mit gefährlichen Stoffen in Kontakt zu kommen."],["Tiefe Krankheiten im Spiel","Die Crezzerin-Konzentration in der Tiefe versengt die Haut und bringt Mutation, ist aber bei Weitem nicht der einzige Überträger von Infektion oder Veränderung – insektenübertragene Parasiten, Flecken schlechter Luft, eingeatmete Sporen und die Berührung wandernder Geister können allesamt bleibende Wirkungen hinterlassen, die sich als Krankheiten zeigen oder zumindest so behandelt werden."]]},
{id:"rinwurm", t:"Rinwurm", en:"Rinworm", kat:"krankheiten", p:170, q:"sr", kurz:true,
 x:"Eine seltene Nebenwirkung von Crezzerin-Verunreinigung, die nur Wildsegler mit irgendeiner Art inneren Skeletts betrifft. Rinwurm zeigt sich in Anfällen intensiven Schmerzes und unerwarteter Muskelkrämpfe, wenn sich ein oder mehrere kleinere Knochen von ihren Nachbarn lösen und nach Belieben auf Wanderschaft durch den Körper gehen. Die sicherste Heilung für Rinwurm ist, den störenden Knochen chirurgisch zu entfernen, was meist erfordert, an seiner ursprünglichen Stelle einen Ersatz einzusetzen."},
{id:"bandnarben", t:"Bandnarben", en:"Ribbon Scars", kat:"krankheiten", p:170, q:"sr", kurz:true,
 x:"Eine arconautische Verletzung, meist von nachlässigen Ravellern erlitten, die Fleisch und Haare fest an Stoff und anderer Kleidung haften lässt. Grobe Bewegungen reißen die festsitzenden Kleider oft ein und hinterlassen „Bänder“ aus Material, die an der Haut kleben und äußerst schwer vollständig zu entfernen sind. Unbehandelte Bandnarben sind meist nur ein leichtes Ärgernis, ziehen aber tendenziell die Aufmerksamkeit der Wachsamen Augen auf sich (was den Abzug bei jeder Aktion unter der Wirkung der Aufmerksamkeit erhöhen könnte)."},
{id:"das-roecheln", t:"Das Röcheln", en:"The Rasp", kat:"krankheiten", p:170, q:"sr", kurz:true,
 x:"Wird nach längeren Phasen des Atmens schlechter oder verunreinigter Luft erworben und macht nichts weiter, als jeden Atemzug zu einem lauten, mühsamen Röcheln zu machen. Es wird dich definitiv nicht töten, erschwert aber wirksame Heimlichkeit und macht es wahrscheinlicher, dass Raubtiere, die nach Gehör jagen, dich aufspüren."},
{id:"lammhaut", t:"Lammhaut", en:"Lambskin", kat:"krankheiten", p:170, q:"sr", kurz:true,
 x:"Ein Leiden, das die Haut weich macht, sei sie Fleisch, Gemüse, Pilz oder Chitin (Ironbound sind glücklicherweise immun, und Ketra mit Lammhaut bemerken es kaum je). Lammhaut richtet für sich genommen keinen Schaden an, senkt aber Immunitäten und Resistenzen eines Seglers um je eine Stufe. Sie wirkt sich jedoch nicht auf bestehende Schwächen aus und erschafft auch keine neuen."},
{id:"labyrinth-lobo", t:"Labyrinth Lobo", kat:"krankheiten", p:170, q:"sr", kurz:true,
 x:"Entsteht meist bei Abtauchenden und Tauchern, die in großer Tiefe arbeiten; die Krankheit beginnt als Beschäftigung mit dem nicht gewählten Weg und wächst zu einer völligen Unfähigkeit, sich zu entscheiden, wenn mehrere unbekannte Richtungen zur Wahl stehen. Die kurzfristige Behandlung von Labyrinth Lobo ist einfach – die Augen zu schließen (oder anderweitig visuelle Sinne zu dämpfen) erlaubt es, Entscheidungen zu treffen, ohne zu sehen, was sonst noch zur Auswahl gestanden hätte. Längerfristige Behandlungen und echte Heilungen haben oft ein Element der Konfrontation mit unbequemen Entscheidungen."},
{id:"skorbut", t:"Skorbut", en:"Scurvy", kat:"krankheiten", p:170, q:"sr", kurz:true,
 x:"Dass ein Wildsegler oder Taucher Skorbut bekommt, ist fast unerhört, denn das Eine, was die Wellen im Überfluss bieten (neben Gefahr), ist frisches Obst und Gemüse. Aber für Aeronauten kann frische Nahrung auf langen Reisen, auf denen eine Landung schwierig wäre, weit schwerer zu finden sein, und einer der ältesten Seefahrerflüche reckt sein hässliches Haupt. Skorbut zeigt sich in frühen Stadien als deprimierende Lethargie, kann aber, wenn er sich unbehandelt entwickelt, die Wucht bei fast jeder Aktion eines Erkrankten senken und Abzug auf Würfe zur Heilung anderer Verletzungen verhängen."},
{id:"stachelmaehne", t:"Stachelmähne", en:"Mane of Quills", kat:"krankheiten", p:170, q:"sr", kurz:true,
 x:"Ein schlichtes Ergebnis einer rätselhaften Krankheit: Bart und Haar eines Patienten verdrehen und verhärten sich zu stachelschweinartigen Stacheln. Obwohl niemand die Quelle oder die wahre Heilung der Erkrankung herausgefunden hat, behandeln manche kampflustigere Erkrankte sie als Vorteil, indem sie ihre Stacheln als Waffe oder zur Verteidigung nutzen."},
{id:"chirurgische-umarmung", t:"Chirurgische Umarmung", en:"Chirurgic Embrace", kat:"krankheiten", p:170, q:"sr", groesse:"Leiden", unter:"Heilung ist nicht immer gesund",
 x:"Von Moskitos übertragen oder durch verunreinigte medizinische Vorräte erworben, fühlt sich die Umarmung sehr wie ein Segen an … bis das Schreien beginnt. Setze die Chirurgische Umarmung ein, um ein Mitglied der Crew zu heilen und es dann weit mehr „Genesung“ auszusetzen, als es erwartet hat.",
 praesenz:{sicht:"Eine schnell verblassende Narbe. Ein Flattern getrockneter Blätter. Ein langsames Beugen alter Knochen. Blut aus Leder.", geruch:"Antiseptikum und frisches Blut.", klang:"Unheilvolle Stille, dann entsetzte Schreie."},
 ressourcen:{proben:["Alle vorhandenen Ressourcen können das Tag „Wiedergänger des Schreiens“ erhalten"], gefluester:["Zu weit getrieben","Mehr als oberflächlich"]},
 aspekte:[["Willkommene Heilung","Die Chirurgische Umarmung sollte als geheime Leiste beginnen; der Erkrankte löscht eine Markierung Schaden von einer Eigenschaft oder heilt eine Markierung einer Verletzung, wann immer sie markiert wird (meist nach Schlaf oder einer guten Mahlzeit). Sind die Eigenschaften und Verletzungen des Erkrankten jedoch vollständig geheilt, sollte die Leiste offengelegt werden – von da an verdirbt jede darauf gesetzte Markierung eine seiner Proben mit dem Tag „Wiedergänger des Schreiens“ (während sie in eine Form grausigen Halblebens „heilen“) oder verbrennt ein Kästchen an einem Teil seiner Ausrüstung (während Felle sich winden und alte Knochen Mark und Fleisch bekommen)."],["Das Grauen","Der Vorgang, dass Tierteile und alte Knochen unerwartet Fleisch wachsen lassen oder Blut spritzen, ist, wie du dir vorstellen kannst, für die meisten Beobachter Morast wert."]],
 eigenheiten:[{t:"Dieser Drache",x:"Manche Stämme der Chirurgischen Umarmung sind noch aggressiver und verbrennen Kästchen auf völlig geheilten Eigenschaften, während sie den Körper zur Mutation zwingen, wie es eine Überdosis Crezzerin täte."},{t:"Gesunde Trennung",x:"Je nach Ton deines Spiels können Gefährten von der Umarmung völlig unberührt bleiben (selbst wenn ihr Besitzer leidet)."}]},
{id:"tagras-griff", t:"Tagras Griff", en:"Tagra's Clutch", kat:"krankheiten", p:171, q:"sr", groesse:"Leiden", unter:"Der Griff des Sturms, der keiner war",
 x:"Eine arconautische Infektion, die sich als langsame Veränderung an Schiff und Crew zeigt, verursacht und verschlimmert durch zunehmende Nähe zum lebenden Sturm, Tagras Greifender Hand. Der Sturm selbst wirkt auf die Welt wie jeder andere, auch ohne Wolken oder Regen, doch es ist die ihn umgebende Krankheit, die Erkrankte langsam seiner wahren Natur gewahr werden lässt. Setze Tagras Griff ein, um Schiff und Crew immer näher an den Substurm, den abwesenden Regen, das lautlose Heulen heranzubringen.",
 praesenz:{sicht:"Das Wort Tagra, in Notizbücher gekritzelt, an den Rand von Karten, in den Staub eines Fensters, in einer Schrift, die niemand recht identifizieren kann, die aber jeder irgendwie lesen kann. Regentropfen, die Oberflächen tupfen wie Löschpapier, aber nie in der Luft gesehen werden.", geruch:"Regen im Wind unter wolkenlosem Himmel.", klang:"Tagra, ein Wort im Wind. Tagra, im Ticken einer Taschenuhr. Tagra, im Knistern unsichtbarer Blitze."},
 ressourcen:{proben:["Nicht ganz Wasser","Tagrapeden"], gefluester:["Da sollte Donner sein","Worte auf einer Seite"]},
 aspekte:[["Alles ist Tagra","Was um Himmels willen ist ein Tagra? Niemand scheint es zu wissen, doch das Wort taucht immer öfter auf, je näher die Crew dem Sturm kommt. In Wirklichkeit zeigt sich der lebende Sturm, bekannt als Tagras Greifende Hand, als Peitschen von Blättern und Ästen, das Gefühl von Regen auf der Haut, alles aus einem wolkenlosen Himmel an einem sonnigen Tag."],["In den Malstrom gezogen","Ist die Infektion weit genug fortgeschritten, werden Schiff, Crew oder beide in eine Pseudowirklichkeit gezogen, eine Version der Welt, in der ein endloser Sturm die Welt gefressen hat. Peitschender Regen und schreiender Wind verhängen Abzug auf Aktionen zum Kämpfen oder Manövrieren draußen auf dem Deck, Blitze und die folgenden Donnerschläge verursachen eine Kombination aus Strom-, Explosions- und Stumpf-Schaden mit hoher Wucht, und bis die Crew einen Weg findet, die Infektion abzuschütteln (durch kluge Alchemie, durch Herausforderung des plötzlich sichtbaren Sturms oder durch andere einfallsreiche Mittel), wird der Morast langsam steigen."]],
 eigenheiten:[{t:"Die Wölfe von Tagra",x:"Getrieben von den Winden nach dem Donner, sind die „Wölfe“ eine Ansammlung aus Schrott und Trümmern naher Häfen, die der Sturm zerstört hat. Sie streifen über die sturmgepeitschten Wellen und greifen alles an, was sich zerlegen und ihrer eigenen Masse hinzufügen lässt. Die Wölfe verursachen im Kampf NK-Scharf- und Stumpf-Schaden, doch ihre Schrottplatz-Gestalten fallen bei dem geringsten Schaden leicht auseinander (formen sich aber neu, wenn der Donner wiederkehrt)."}]},
{id:"sternenkrankheit", t:"Sternenkrankheit", en:"Star-Sickness", kat:"krankheiten", p:171, q:"sr", groesse:"Leiden", unter:"Man kann nur verlieren, wie’s scheint",
 x:"Ein Leiden, das meist die Kosmer-Satellitenbewohner trifft, aber jeden Aeronauten betreffen kann, der genug Zeit nachts in der Luft verbringt. Die Sternenkrankheit tritt paradoxerweise am stärksten bei denen auf, die den Blick der Sterne meiden, und trifft ziemlich grausam deren Crewkameraden stärker als den eigenen Körper. Setze die Sternenkrankheit ein, um unvorsichtigen und übervorsichtigen Aeronauten gleichermaßen die Gefahr der Aufmerksamkeit vor Augen zu führen.",
 praesenz:{sicht:"Polypen, die bei Sonnenuntergang leuchten.", geruch:"Brennendes Zinn, ein Geruch, so unvertraut, dass die meisten ihn nicht einordnen können.", gefuehl:"Ein Gefühl von Leere und Hunger, das von einem Freund ausstrahlt."},
 ressourcen:{proben:["Nachthimmel-Polyp","Starbuncle"], gefluester:["Unerschütterliche Aufmerksamkeit","Augen an ungewissen Orten"]},
 aspekte:[["Himmelsblick","Die Polypen, die sich auf der Haut eines Erkrankten bilden, umgangssprachlich „Starbuncles“ genannt, leuchten nicht nur – sie beobachten. Jede Crew, die in Sichtweite dieser Starbuncles in der Höhe Aktionen ausführt, erhöht den Abzug um eins, wenn sie von der Aufmerksamkeit betroffen wäre."],["Sanftes Leuchten","In der richtigen Situation ein Vorteil: Die Polypen werfen ein sanftes Sternenlicht, sobald die Sonne zu sinken beginnt, das bis zum Morgengrauen anhält."],["Aura des Hungers","Während ein an der Sternenkrankheit Erkrankter meist einen völlig normalen Appetit hat, fühlen sich andere Crewkameraden in seiner Gegenwart gezwungen, mehr als üblich zu essen."]],
 eigenheiten:[{t:"Ausbrennen",x:"Eine seltene, aber verheerende Nebenwirkung, bei der ein Polyp unerwartet platzt und NK-Flammen-Schaden sowohl am Erkrankten als auch an jedem im Explosionsradius verursacht."}],
 extra:[["Mittlere Begegnung – Albatros (Leiste ○○○○○○○+○○○)","Eine fliegende Kreatur, die sehr wohl ein echter Albatros sein kann, hat beschlossen, sich an einer schwer erreichbaren Stelle am Luftschiff der Crew niederzulassen. Sie leidet an der Sternenkrankheit, und obwohl sie sich tagsüber als weitgehend harmlos erweist, erhöht sie die Gefahr beim Arbeiten oder Kämpfen draußen auf dem Deck während der Nachtstunden dramatisch. Die Kästchen bis zum ersten Bruch werden jedes Mal markiert, wenn sie einen Wurf beeinflusst, indem sie unter der Wirkung der Aufmerksamkeit Abzug hinzufügt, doch sobald der Bruch erreicht ist, tritt sie in einen Zustand des Ausbrennens ein, wahnsinnig vor Schmerz, und verbreitet kleine Brände um das Gefährt, während die Crew unweigerlich versucht, sie zu verscheuchen oder zu fangen."]]},
{id:"sirenenruf", img:"sirenruf", t:"Der Sirenenruf", en:"The Siren's Call", kat:"krankheiten", p:172, q:"sr", groesse:"Leiden", unter:"Verbreitet durch tragische, lange verlassene Überreste",
 x:"Selbst für jene, die sich so gut wie möglich vorbereiten und alle vernünftigen Vorkehrungen für einen Abstieg unter das Geflecht treffen, ist die Wirklichkeit des Drucks unmöglich wirklich vorherzusehen. Für manche Crews ist es ein Gefühl des Unbehagens, das sich mit der Tiefe verschlimmert, für andere ein Knarren in der Schiffsstruktur, das zum Schrei sich verdrehenden Metalls oder zum Stöhnen splitternden Holzes wird, für wieder andere eine bedrückende Stille, oder ein vertrautes Gesicht, wo es unmöglich sein kann, oder das Kratzen missgebildeter Klauen am Fenster …\nUnd für manche, die Unglücklichsten, ist es ein gähnender Ruf, der unmöglich zu ignorieren ist – ein Gefühl der Zugehörigkeit.\nEr setzt sich in Ohr und Kehle und Gehirn fest. Er verdreht Knochen, lässt Saft brutzeln und führt Crezzerin in die geheimen Räume des Herzens.\nManchmal verstopft ein Taucher sich die Ohren oder schlägt sich bewusstlos und verlässt sich darauf, dass seine Gefährten ihn zurückziehen oder festzurren. Solche Personen kehren an die Oberfläche zurück und setzen kaum je wieder einen Fuß auf das Deck eines Schiffs, geschweige denn eines Tauchboots. Sie haben die Flüstern in der Dunkelheit gehört – nicht einmal ein Ruf der Unter-Traufe, sondern etwas Vitaleres, Heimtückischeres; den Sirenenklang der erstickenden, druckgekochten Schatten darunter. Sie sind infiziert, aber es ruht, und sie wissen, wie sie ein Wiederaufflammen vermeiden.\nAber öfter werden sie von den Wellen beansprucht, kämpfen sich entweder durch ihre verwirrten und entsetzten Gefährten oder werden im schlimmsten Fall von ihnen angetrieben oder begleitet. Der Sirenenruf ergreift schnell Besitz, und sie geben dem Druck nach und werden Teil des Ökosystems, in das sie nur eintauchen sollten … eine Tiefensirene. Setze den Sirenenruf ein, wenn die Crew in einem aussichtslosen Wettlauf in die Tiefe gegen ihre eigenen Überlebensinstinkte und ihre Mitsegler kämpfen soll … Oder setze eine voll infizierte Tiefensirene als mahnendes Beispiel dafür ein, was geschieht, wenn der Druck zu groß wird, entweder in Gestalt eines einzelnen, verdrehten Individuums oder einer ganzen tiefengezeichneten Crew.",
 praesenz:{klang:"Ein Murmeln durch die Äste, das zu einem eindringlichen, lockenden Brüllen anschwillt. Eine Symphonie einladenden Wahnsinns, die viel zu viel Sinn ergibt.", gefuehl:"Dass du zum ersten Mal nach Hause kommst."},
 ressourcen:{bergegut:["Rissige Anzugpanzerung","Zersplittertes Visier","Bröckelnde Schläuche"], proben:["Wandelbares Fleisch","Überwucherte Blumen","Verzogener Knochen","Zuckende Augenknospe"], gefluester:["Ruf aus der Tiefe","Finster unwiderstehlich"], seekarten:["Ein abgeschriebener Satz sterbender Worte"]},
 aspekte:[["Rasches Fortschreiten","Obwohl der Ruf selbst im Lauf der Zeit langsam wächst, erlaubt der Kontakt mit einer Tiefensirene, ihn klar und sofort zu hören, ohne die Dämmung durch Entfernung oder Missverständnis. Ein Segler, der den Ruf direkt von einer anderen Sirene hört, hat nur Augenblicke zum Reagieren, bevor sein Drang zur Tiefe überwältigend wird. Sich selbst zu ertauben kann wirksam sein, und sich festzubinden oder anderweitig zu fesseln kann helfen, den ersten Impuls auszusitzen. Dem Ruf zu widerstehen wird mit der Zeit leichter, und Segler, die Tiefensirenen bei mehreren Gelegenheiten begegnet sind, könnten ihm sogar völlig unbeeinflusst gegenüberstehen."],["Unsterbliche Elite","Eine voll infizierte Tiefensirene zu töten ist möglich … aber selten ohne Vorbedacht, riesige Mengen Glück und die direkte, wiederholte Anwendung massiven Schadens. Es liegt nicht daran, dass sie besondere Resistenzen hätten, sondern dass sie fast augenblicklich mutieren und heilen, wenn ihnen Schaden normaler oder auch hoher Wucht zugefügt wird. Strategie-Leisten, die für eine Begegnung mit einer Tiefensirene angelegt werden, sollten durch gemeinsame Anstrengung gefüllt werden, sie zu fangen, vor ihr zu fliehen oder sie völlig zu zermalmen und zu zerstückeln … Oder, um ganz sicherzugehen … Verbrenne sie. Die einzige herkömmliche Schwäche einer Tiefensirene ist Flamme."],["Dekompression","Der einzige Hoffnungsschimmer bei vielen Sirenen-Begegnungen ist, dass sie Senke und Tiefe nie freiwillig verlassen. Der Aufstieg ins Geflecht lässt sie eine grässliche Dekompression durchmachen, und bis sie das Gestrüpp erreichten, wäre ihr Leichnam kaum noch als je zu einer Blutlinie der Wildsee gehörig zu erkennen."],["Der Körper ist eine Waffe","Jeder Teil eines vom Ruf Betroffenen mutiert zu etwas, das ihm in der Tiefe einen Vorteil verschaffen könnte – zusätzliche Gliedmaßen, Mäuler und Klauen sind häufig, und die Kleidung und Ausrüstung, die sie trugen, als sie dem Ruf nachgaben, hat sich mit ihnen verändert. Tiefensirenen können als Selbstverständlichkeit mittleren bis schweren Stumpf-, Scharf-, Stich-, Säge-, Hieb-, Gift- oder Säure-Schaden verursachen, bei NK oder FK."]],
 extra:[["Zurück vom Abgrund","Viele geben sich dem Ruf hin, und nur die Seltensten werden von ihren Crews aus der Dunkelheit des Unter-Gestrüpps zurückgeholt, bevor sie Zeit hatten, sich in eine Tiefensirene zu verwandeln. Selbst dann sind sie für immer gezeichnet, verändert zu etwas, das nicht ganz sie selbst ist – Avatare dessen, was hätte sein können, in der endlosen Nacht der Tiefe."],["Siren’s Touch · 3-Leisten-Komplexe Eigenschaft","Du bist vom Abgrund zurückgekehrt, aber für immer von der Tiefe verändert. Wenn du Siren’s Touch als Aspekt wählst, erhält er zwei Vorteile deiner Wahl aus der folgenden Liste … · Neues Maul: Du trägst ein neues Maul mit knirschenden Zähnen an einer Stelle, wo nie ein Maul sein sollte. Du kannst NK-Stich-Schaden verursachen und bist immun gegen die Wirkungen verschluckten Crezzerins. · Fleischblüten: Nicht die gesündeste Form der Verteidigung, aber eine wirksame. Du erhältst Resistenz gegen alle Schadensarten, die von in Senke und Tiefe heimischen Gefahren verursacht werden. · Eins mit dem Anzug: Der Taucheranzug, den du trugst, ist mit dem Rest deines Körpers verschmolzen. Du bist immun gegen Explosions-Schaden und widerstehst den Wirkungen schlechter Luft. · Überwuchs: Dein Körper hat sich gespalten, aufgebläht und auf ungewöhnliche Weise verlängert. Ignoriere Abzug auf Aktionen, um dich durch das Unter-Gestrüpp zu bewegen, und behandle alle NK-Schadensarten, die du verursachen kannst, als wären sie NK oder FK. Und ein Nachteil … · Sonnenscheu: Du bist bei direktem Sonnenlicht schwach gegen alle Schadensarten. · Aufgebläht: Abzug bei Versuchen zu bewegungsbasierten Aktionen, die Heimlichkeit oder Präzision erfordern. · Vom Dunkel angezogen: Wann immer du oder ein Mitglied deiner Crew das Natur-Ergebnis eines Wache-Wurfs erhält, macht das Glühwürmchen zwei Bedrohungswürfe und nimmt das schlechtere Ergebnis."],["Präsenz – Tiefensirenen","Sicht: Einst vertraute Gestalten, die nun schlurfen oder schlängeln oder hangeln. Druckanzüge, die sich der Grausamkeit der Tiefe öffnen. Abgetrennte Schläuche, die sich wie Ranken winden. Bernsteinglas-Splitter, einst Visiere, nun Zähne. Ein aufragendes Gefährt in der Dunkelheit, das Gestalten aus geborstenen Luken ausspeit. Klang: Schreie, Schluchzen, Heulen, Gesang … Jede Tiefensirene verbreitet den Ruf auf ihre eigene Weise, aber keine ist je still."]]},
{id:"blindes-sehen", t:"Blindes Sehen", en:"Sightless Sight", kat:"krankheiten", p:179, q:"sr", groesse:"Leiden", unter:"Einzigartige arconautische Krankheit · Strafende Neugier",
 x:"Man findet sie in den dunkleren Ecken von Kreuzungshäusern oder verkrochen in Schattenquellen – Wildsegler, deren Körper von augenartigen Einkerbungen gezeichnet sind, manche einen Zoll tief, manche, die einen Pfad von einer Seite zur anderen schneiden. Diese Personen sind verflucht (der Begriff ist ungenau), den eigenartigen Abwehrmechanismus des Monument Potoo zu erleiden. Setze das Blinde Sehen als Katerstimmung für Spieler ein, die beim Abtauchen ins Innere des Monument Potoo etwas zu abgelenkt wurden, oder für jene, die davon besessen sind, ihn zu finden.",
 praesenz:{sicht:"Ja. Viel zu viel davon."},
 ressourcen:{gefluester:["Du wurdest wahrscheinlich gewarnt"]},
 aspekte:[["Leere Augen","Die Löcher bei einem vom Blinden Sehen Betroffenen wirken wie Augen, die sich nie schließen lassen, was es den Erkrankten fast unmöglich macht zu schlafen, sich auf einzelne Objekte zu konzentrieren oder helles Licht zu ertragen, ohne überwältigt zu werden. Die meisten Betroffenen halten sich nach Möglichkeit an dunklen Orten auf oder versuchen, diese neuen „Augen“ zu verbinden oder anderweitig zu bedecken, doch die Wirkung ist begrenzt."],["Der Fluch der Neugier","Obwohl diese Krankheit sich meist nur bei denen zeigt, die mit dem Potoo in Berührung gekommen sind, erwischt es gelegentlich auch jene, die zu tief in seine Geheimnisse eindringen (selbst aus der Ferne) oder Gegenstände handhaben, die aus seinem Inneren geplündert wurden, mit einem Fall von Blindem Sehen."]],
 eigenheiten:[{t:"Heilender Stein",x:"Es gibt Gerüchte über eine Heilung, bei der lebender Stein vom schwebenden Kamm des Potoo genommen und zu korkenartigen Stöpseln geformt wird. Es sind aber nur Gerüchte."}]},

/* ===== Leviathane (S. 174–185) ===== */
{id:"sr-leviathane", t:"Leviathane in Höhe und Tiefe", en:"Leviathans", kat:"leviathane", p:174, q:"sr", kurz:true,
 x:"Viele Kartografen tragen Leviathan-Aktivität in ihre Karten ein, denn selbst wenn die Bestien weitergezogen sind, kann es für andere nützlich sein zu wissen, wo sie gewesen sind. In den Himmeln ist das schwieriger, da das Kartieren der Himmel schon zu den besten Zeiten ein beschwerliches Unterfangen ist … und in der Tiefe unmöglich, da die Dichte an Leviathan- und Protoleviathan-Aktivität solche Dokumente zu verwirrend (und möglicherweise zu furchterregend) zur Verwendung machen würde.",
 extra:[["Leviathane der Höhen im Spiel","Luftleviathane sind im Wilden Blau nicht häufig, wegen der enormen Energie, die nötig ist, um irgendein Geschöpf ab einem bestimmten Gewicht in die Luft zu bringen. Weit gefährlicher sind Goliaths der Wellenkämme, die für kurze Schübe zwischen den Wolken operieren können, oder Kreaturen und Geister, die sich entwickelt haben oder zufällig in irgendeine Anpassung hineingeraten sind, die ihnen eine von der Schwerkraft losgelöste Bewegung verleiht. Protoleviathane hingegen sind weit häufiger – groß genug, um eine ernste Bedrohung für ein Schiff darzustellen, aber nicht so groß, dass sie sich schon durch bloßes Existieren erschöpfen."],["Leviathane der Tiefen im Spiel","Das Unter-Gestrüpp dient der Mehrzahl der Leviathane als natürlicher Lebensraum, mit ineinandergreifenden Ästen, die groß genug sind, sie bei Bewegung und Ruhe zu tragen, einem Element der Abgeschiedenheit von den Jägern der weit darüber liegenden Wellen und unzähligen Nahrungsquellen in der Nähe. Das unglückliche Ergebnis ist, dass ein Tauchboot, wenn es tiefer abtaucht, standardmäßig in ein Gebiet eindringt, das bereits von Bedrohungen beansprucht wird, die weit größer sind, als die meisten vernünftig bewältigen könnten. Zum Glück halten die Leviathane der Tiefe nicht ständig Wache nach Eindringlingen, schon gar nicht nach solchen, die in etwas so lasch Schmeckendes wie die Hülle und Druckhülle eines Tauchboots gehüllt sind. Das ist der Vorteil der Tiefe; alles dort unten mag eine potenzielle Bedrohung für einen Segler sein, aber viele von ihnen sind auch Bedrohungen füreinander. Die Pyramiden aus Raubtier, Beute und Opportunist verschieben sich in den erdrückenden Tiefen ständig, und obwohl Leviathane oft nahe der Spitze stehen, unterliegen selbst diese hohen Positionen dem Wandel."]]},
{id:"the-mangrove", img:"mangrove", t:"The Mangrove", en:"The Mangrove", kat:"leviathane", p:174, q:"sr", groesse:"Leviathan-Eisenwurzel", unter:"Greifend nach verlorenen Leben",
 x:"Glücklicherweise unbeweglich, aber nicht weniger gefährlich deswegen. Auf Wellenhöhe könnte man die Mangrove für eine Eisenwurzel wie jede andere halten, deren Äste mit runzligen weißen Früchten zwischen fahlgrünen Blättern behangen sind und die vielleicht ein besonders verlockend aussehendes Wrack hält. Das Abtauchen unter das Blätterdach enthüllt die Wahrheit der Mangrove – eine Rinde, gespickt mit Körpern, deren Leichen zuerst den Stamm nährten und dann direkt in ihn eingegliedert wurden. Sie weidet sich an Wellenwanderern und Fruchtpflückern, und einige der sich noch bewegenden Überreste tragen die Fetzen von hundert Jahre altmodischer Kleidung.\nDie relativ sichere Krone der Mangrove breitet sich über Meilen aus, manchmal von anderen, weniger räuberischen Bäumen überwuchert, manchmal völlig frei liegend. Obwohl der Leviathan selbst in keinem herkömmlichen Sinne zu besiegen ist, lassen sich diese oberen Äste durchsägen, um seinen Einflussbereich zu verringern. Setze die Mangrove ein, wenn Crews einem gewaltigen, aber unkonventionellen Leviathan gegenüberstehen sollen, der nur für jene eine Gefahr darstellt, die sich nahe genug heranwagen, um sich mit ihm einzulassen.",
 antriebe:[["Ergänzende Nahrung","Man vermutet, dass die Wurzeln der Mangrove der aufgewühlten Erde der Traufe nicht genug entnehmen, was den Baum im Lauf der Jahre dazu trieb, sich räuberischeren Taktiken zuzuwenden."]],
 praesenz:{sicht:"Olivfarbene Blätter, die im Wind rascheln, fahle verschrumpelte Früchte, greifende Hände und ratschende Mäuler.", klang:"Ein leises Stöhnen von unterhalb der Wellenkämme.", geruch:"Vor allem Fäulnis."},
 ressourcen:{bergegut:["Verdrehte Axt","Stumpfe Säge"], proben:["Abgebrochener Mangrove-Ast","Hungrige Rinde","Mangrove-Frucht"], gefluester:["Ineffiziente Wurzeln","Ein Hunger nach Seglern","Shank und Shank"], seekarten:["Seite mit abgeschriebenem Murmeln"], fracht:["Sarkophag-Holz","Mangrove-„Überlebender“"]},
 aspekte:[["Leviathan-Krone","Die Mangrove ist ein wahrer Leviathan (behandelt eingehenden massiven Schaden als normalen Schaden), aber auch eine Eisenwurzel – sie kann nicht „zurückgeschlagen“ oder zur Flucht gezwungen werden, sie ist in der Dunkelheit der Unter-Traufe verwurzelt. Außerdem ist die Mangrove völlig immun gegen Gift- und Salz-Schaden, aber die oberen Teile und die Leichen, die sie sammelt, können schwach gegen Hieb-, Säge- und Flammen-Schaden sein."],["Greifende Glieder","Die Mangrove greift mit den Leichen derer an, die sie eingegliedert hat, und verursacht je nach Biologie der darin gefangenen Unglücklichen unterschiedlichen Schaden und Wirkungen. Statt des üblichen Abschnitts Eigenheiten bietet der Abschnitt Körper unten mehrere Angriffsoptionen."]],
 extra:[["Körper: Ardent","Kratzend und keifend schlagen Ardent-Körper mit den Waffen um sich, die sie bei ihrem Tod umklammerten. Ihre Lautäußerungen verursachen Morast, und ihre Angriffe verursachen meist NK-Scharf-, Stumpf- oder Säge-Schaden."],["Körper: Ektus","Eingegliederte Ektus werden zu einem festen Bestandteil des Sinnesnetzes der Mangrove; Irisblüten dienen als scharfe visuelle Eingabe, und Stacheln werden zu Fühlern."],["Körper: Gau","Wenn ein Gau von der Mangrove gefangen wird, läuft seine pilzartige Natur Amok, was ihn auf ekelhafte Weise dehnt und verzerrt. Diese feisten Massen setzen einen steten Strom bewusstseinsverändernder Sporen frei."],["Körper: Ironbound","Obwohl ihre Körper gefangen sind, schlagen wahnsinnige Ironbound-Seelen aus und verursachen NK- oder FK-Salz-Schaden."],["Körper: Itzenko","Morbide Chitin-Bomben; eingegliederte Itzenko ruhen friedlich, bis sich eine Bedrohung für die Mangrove nähert. Die folgende biologische Explosion verursacht schweren Scharf- oder Stich-Schaden, wobei sich Fragmente in Opfern festsetzen und bleibende Verletzungen hinterlassen."],["Körper: Ketra","Die gallertartige Masse, aus der der Körper eines Ketra besteht, reicht weit über das normal Mögliche hinaus und erlaubt FK-Stumpf- und Säure-Angriffe."],["Körper: Mothryn","Anders als alle anderen weit verbreiteten Blutlinien sind die Mothryn vor der Aufnahme durch die Mangrove sicher. Nicht aber vor Angriffen."],["Körper: Tzelicrae","Mangrovenrinde hält Spinnen schlecht, aber wenn sie genug davon einfängt, kann sie einen ganzen Schwarmgeist eingliedern. Diese noch beweglichen Schwärme huschen wild umher, lenken Gegner ab und beißen für NK-Gift-Schaden."]]},
{id:"the-raahe", t:"The Raahe", en:"The Raahe", kat:"leviathane", p:176, q:"sr", groesse:"Leviathan-Schlundschiff", unter:"Eine Abwesenheit von Hunger, eine Fülle von Einsamkeit",
 x:"Schlundschiffe sind ebenso für ihren Appetit wie für ihre Brutalität bekannt, ihren Hunger nach einer Crew, die die verlorenen Segler ersetzt. Es ist ein grundlegender Aspekt von ihnen, eines der wenigen Elemente ihrer Existenz, die wirklich verstanden sind.\nAber wie es in der Wildnis üblich ist, gibt es von jeder Regel Ausnahmen.\nDie Raahe war ein Triumph – ein Schlachtschiff, gebaut, um Jahre auf den rauschenden Wellen zu verbringen, so schwer und groß, dass der Boden des Rumpfs tief durch das Geflecht schnitt und fast die Senke küsste. Sie hatte eine Crew aus Hunderten, Ardent und Ektus und Ketra und mehr; sie waren einst eine wurzellose Flottenfamilie gewesen, doch Ehrgeiz und Verlangen hatten sie immer enger zusammengezogen, bis ein einziges Schiff so viel vernünftiger schien als eine Ansammlung kleinerer Gefährte.\nUnd es funktionierte, eine Zeit lang. Es funktionierte gut. Die Raahe war groß genug, um Leviathane abzuwehren, mit genug Vorräten bestückt, um Winter ohne Anlaufen eines Hafens zu überstehen, und so imposant, dass selbst die ehrgeizigsten Piratenfraktionen kehrtmachten und flohen, wenn sie ihr Gebiet betrat. Ihr Bau hatte Jahre gedauert und noch viel mehr Jahre des Handels und Materialsammelns zur Finanzierung, doch in vollendetem Zustand war sie wahrlich ein Wunderwerk.\nEs gibt widersprüchliche Theorien darüber, was genau zum Untergang des Schiffs führte, manche glaubwürdiger als andere. Taucher mutmaßen, dass das Experimentieren der Raahe, auf ihrer Reise immer tiefer in die Wellen einzutauchen, etwas im Schiff oder in der Crew Wurzeln schlagen ließ – vielleicht ein Sirenenruf. Mesmer sprechen von den Nebeln, die das Schiff mit sich bringt, und woher diese Nebel stammen könnten, und von den Wachträumen, die sie bringen könnten. Andere wurzellose Flottenfamilien beharren darauf, dass es das natürliche Ergebnis ist, wenn man den Wert der Selbstbestimmung vergisst, von Distanz-und-Nähe zusammen. Rasselhände schnalzen mit den Zungen, wenn sie welche haben, und sprechen von der Torheit, in titanischen Ausmaßen zu bauen und das Aufkommen von Intelligenz nicht zu regulieren.\nWelche Theorie auch stimmt, das Ergebnis steht nicht in Frage. Irgendwann, vor etwa fünfzig Jahren, versanken die höchsten Schornsteine der Raahe unter dem Gestrüpp, und es dauerte Jahre, bis das Schiff wieder auftauchte. Und als es das tat … Nun, es gibt Schlimmeres, als auf See verloren zu gehen.\nSetze die Raahe ein, wenn die Crew einem Leviathan gegenüberstehen soll, der kein Interesse daran hat, sie zu verletzen (mehr als nötig jedenfalls), sondern stattdessen versuchen wird, sie zu entführen und in sich einzugliedern. Einem, der nicht zum Zerstören getrieben ist, sondern zum Sammeln.",
 erzaehl:"Es begann mit Gestalten, die durch den Nebel trieben.\n… Oder vielleicht begann es viel früher.\nVielleicht, als die Nebel hereinrollten, die klebrige Feuchte, die den Gestank der Senke zu bringen schien, das Licht der Morgendämmerung überwältigte und Rufe der Furcht und der Beruhigung gleichermaßen erstickte.\nVielleicht war es das ferne Horn, das durch denselben Nebel schnitt, das einzige klar klingende Geräusch. Eine Warnung, ein Signal, etwas Dunkleres … Die Unterbesatzung hatte es debattiert, über Bombardier-gedämpftem Reis, der zwischen Schale und Mund sauer wurde.\nVielleicht war es das Leben der Wellen, oder dessen Fehlen. Die Springfüchse, die wie Delfine im Kielwasser des Schiffs getanzt hatten, blieben zurück, ersetzt durch Massen hundegroßer Asseln, die in einem Gewirr aus Panzern übereinander krabbelten.\nAber wie auch immer es begann, die Gestalten waren jetzt da – treibend, still und jeden Tag näher.",
 antriebe:[["Der Familie hinzufügen","Es ist nicht ein Hunger nach Ersatzcrew, der die Raahe antreibt, sondern der nach Zuwachs für die Crew, die sie schon umsorgt (obwohl der Standard dieser Fürsorge sehr in Frage steht). Sie sucht neues Leben, heißes Blut, frische Seelen, und die Segler, die sie bereits hält, sind darauf ebenso erpicht wie das Schiff selbst."]],
 praesenz:{sicht:"Ein Koloss, der durch die Nebel aufragt und unaufhaltsam durch Äste und Stämme und kleine Siedlungen kracht, während er dein Schiff aufspürt. Die Crew, zum Tauchen gekleidet, schlaff durch die Luft um das Schiff schwebend, verbunden durch uralte Luftschläuche. Krabbelnde Asseln, die die Wellenkämme füllen, aus der Senke heraufgebracht.", geruch:"Eine kalte, durchdringende Feuchte. Verdorbene Lebensmittelvorräte. Der saure Beiklang getrockneten Crezzerins.", klang:"Das Nebelhorn der Raahe, das einen Ruf (oder eine Warnung, wenn man großzügig sein will) bläst. Schweigen von der hängenden Crew, obwohl Sprecher von Altem Handzeichen gelegentlich ein flehendes Wort unterscheiden können.", gefuehl:"Glitschiger Nebel, der jede Oberfläche schlüpfrig macht und jeden Atemzug zu einem Schluck Tiefe. Eine unnatürliche Kälte, egal zu welcher Jahreszeit."},
 ressourcen:{proben:["Verdorbene Mahlzeit","Asselpanzer","Flasche kalter Nebel"], bergegut:["Korrodierte Anzugteile","Raahe-Stahl"], gefluester:["Die Familieneinheit","Der letzte Tauchgang","Die Kälte der Isolation","Gestalt im Nebel"], seekarten:["Ein Raahe-Reisetagebuch","Nebel-Abtauch-Karte"], fracht:["Raahe-Panzerung","Kiste verdorbener Vorräte"]},
 aspekte:[["Fein geschmiedeter Stahl","Die Segler der Flottenfamilie, die die Raahe zusammensetzten, nutzten die modernsten Bautechniken, die sie konnten, und reisten viele Reichweiten weit auf der Suche nach den perfekten Materialien und Verfahren. Obwohl sie einst bloß ein Schiff war, zählt die Raahe nun als wahrer Leviathan: Sie behandelt eingehenden massiven Schaden als normalen Schaden. Der Außenrumpf ist außerdem völlig immun gegen Scharf-, Stumpf-, Gift-, Frost- und Flammen-Schaden, unabhängig von der Wucht."],["Die Nebel","Obwohl das Schiff selbst massiven Stumpf-Schaden verursachen kann, während es durch die Wellen vorankommt, versucht es normalerweise nicht wirklich, die Gefährte anzugreifen, denen es folgt – anders als die meisten Schlundschiffe überlässt es das der noch in ihm lebenden Crew. Aber das Schiff bringt überall, wo es segelt, einen eisigen Nebel mit, der aus einem riesigen Riss im Stahl der Steuerbordseite quillt. Die Aussetzung gegenüber diesen Nebeln markiert Morast und verursacht zunehmende Mengen Frost-Schaden bei jedem, der nicht auf die Kälte vorbereitet ist, und wer dem Schiffskörper nahekommt, erleidet wahrscheinlich auch crezzerin-basierten Gift-Schaden."],["Das Horn & die Senke","Ob beabsichtigt oder nicht, das Nebelhorn der Raahe neigt dazu, die Geschöpfe der oberen Wellen zu vertreiben und Bewohner der Senke herbeizulocken, besonders Insekten. Diese können für ein fliehendes Schiff manchmal ein größeres Problem sein als die Raahe selbst, denn diese Schwärme können stechen und beißen (und verursachen NK-Gift- und Stich-Schaden, dem man schwer ausweichen kann) und neigen dazu, Schiffe zu überrennen und sich in Abgasöffnungen und im Motoreninneren festzusetzen, sodass Sägen- und Tempo-Werte verringert sind, bis die Verstopfungen beseitigt sind."]],
 eigenheiten:[{t:"Käfig wird zur Klaue",x:"Falls etwas die Raahe zur Verteidigung treibt, etwa eine Bedrohung durch einen anderen Leviathan oder schwere strukturelle Schäden, quellen käfigartige Tauchglocken am Ende von Seilen und Ketten aus demselben Loch im Rumpf, aus dem die Nebel dringen, und schlagen wie Tentakel. Das Zuschnappen dieser Käfige kann NK-Scharf- oder Säge-Schaden mit hoher Wucht verursachen, und ein unglücklicher Wildsegler kann in einem gefangen und ins Innere des Schiffs zurückgezogen werden."},{t:"Aufgeben",x:"Die Raahe verfolgt Schiffe tagelang, gibt aber fast immer auf, wenn dieses Schiff einen Hafen erreicht. Der Grund dafür ist unbekannt, besonders da sie bei der Verfolgung eines fliehenden Ziels geradewegs mitten durch eine Landzunge segelt."}]},
{id:"die-herrschaften", t:"Die Herrschaften", en:"The Gentlefolk", kat:"leviathane", p:177, q:"sr", groesse:"Mittlere Leviathan-Begleiter", unter:"Weniger als Geister, mehr als eine Crew",
 x:"Wer die Herrschaften gesehen hat, vergisst es selten; sie werden von Bildern heimgesucht, wie Gestalten lautlos durch die Luft treiben, noch immer in Druckanzügen mit Raahe-Zeichen, und wie Finger sich im Nebel beugen. Sie sind nicht tot, die Herrschaften – es gibt keinen Aasgestank, keinen Hauch durchsickernder Seele. Aber sie sind auch nicht ganz lebendig, jedenfalls nicht auf die Weise wie einst. Setze die Herrschaften ein, wenn die Crew in der Nähe der Raahe einer persönlicheren Bedrohung gegenüberstehen soll – einst stolze Flottenfamilien, die zu Begleitern eines einsamen Monstrums wurden.",
 antriebe:[["Ein Ende","Der Kälte. Der Stille. Allem."],["Fangen & Freilassen","Die Herrschaften ringen mit ihren Zielen, ziehen sie in die Luft und zurück zu dem Schiff, mit dem sie verbunden sind."]],
 praesenz:{sicht:"Schlaffe Gestalten, die näher kommen. Sich öffnende und schließende Hände. Gummi-Nabelschnüre, die sich unnatürlich biegen.", klang:"Nichts, bis ihre Sauerstoffschläuche durchtrennt werden.", geruch:"Beunruhigend und unmöglich einzuordnen, aber er erinnert an die Senke."},
 ressourcen:{bergegut:["Raahe-Taucheranzug","Schlauchgummi"], gefluester:["Ein Geist wäre besser","Gefundene Familie"]},
 aspekte:[["Greifende Hände, stiller Atem","Die Herrschaften tragen keine Waffen und ziehen es vor, ihre Ziele zu packen und in die Luft zu heben. Aber das lässt sie nicht schutzlos – wenn sie überwältigt oder festgehalten werden, können sie die Visiere ihrer Druckanzüge öffnen und Strahlen eisigen Nebels freisetzen, die NK- (oder bei größeren Herrschaften FK-) Frost-Schaden verursachen. Hinter diesen Visieren sind Gesichter, aber sie sind bleich und ausdruckslos."],["Nabelschläuche","Das einzige Mal, dass man einen Laut von einer der Herrschaften hört, ist, wenn einer der dicken Gummischläuche, die sie mit dem fernen Deck der Raahe verbinden, durchtrennt oder zerbrochen wird. Die daraus folgenden Schreie markieren mit ziemlicher Sicherheit Morast, doch die betroffene Herrschaft fällt auch wie ein Stein, windet sich einige Sekunden und wird dann still."]],
 eigenheiten:[{t:"Letzter Atemzug",x:"Eine der Herrschaften erlangt, mit gekappter Verbindung zur Raahe, in den Augenblicken vor ihrem Tod einen Bruchteil ihres Geistes zurück und kann einige Fragen beantworten oder mit klappernden Zähnen eine Reihe letzter Worte aussprechen."}]},
{id:"the-monument-potoo", img:"monument-potoo", t:"The Monument Potoo", en:"The Monument Potoo", kat:"leviathane", p:178, q:"sr", groesse:"Faux-Leviathan", unter:"Wandelnde Vogelinsel",
 x:"Wenn Stürme leben können, warum nicht Stein? Das war vielleicht der Gedankengang hinter dem Bau des Monument Potoo, eines der wenigen „Leviathane“, die nicht durch die inhärenten Eigenheiten der Wildnis oder die Verheerungen des Crezzerins geschaffen wurden, sondern durch arconautisches Können und beeindruckende (wenn auch fehlgeleitete) Ingenieurskunst.\nDie Einzelheiten des Entwurfs des Potoo gingen fast im Augenblick seiner Entstehung verloren, da die Geburt der Insel zum Bewusstsein die unglückliche Nebenwirkung hatte, die Werkstätten und Gießereien ihres hohlen Inneren zu Ruinen zu zermahlen. Doch Geheimnisse liegen noch immer im Inneren des Geschöpfs, und übermütige Crews suchen die Bestie auf, in der Hoffnung, ihre Schiffe durch den klaffenden Steinschnabel zu steuern und die gerüchteweisen arcotechnologischen Reichtümer darin zu plündern.\nDie lebende Insel widersetzt sich, wie man erwarten kann, solchen Eindringlingen. Obwohl das Netz leerer Augen, das ihre Flanke hinabläuft, natürlich blind sein muss, besitzt das Geschöpf einen beeindruckenden Selbsterhaltungstrieb. Schiffe, die ohne Vorbereitung oder Strategie nahekommen, werden entweder vom gewaltigen Schnabel zermalmt oder, falls sie den ersten Angriff überleben, vom arconautischen Schrecken des blinden Sehens heimgesucht. Setze den Monument Potoo ein, wenn die Crew einem Leviathan gegenüberstehen soll, bei dem es nicht darum geht, ihn zu zerstören, sondern sein Inneres zu erkunden (und hoffentlich mit Schiff und Beute heil zu entkommen).",
 antriebe:[["Alte Geheimnisse horten","Obwohl die Gedankengänge des Monument Potoo so undurchschaubar sind, wie man es von einer Bestie aus empfindungsfähigem Stein erwartet, ist das praktische Ergebnis seines Verhaltens klar. Das Innere des Potoo birgt Geheimnisse, und er will sie dabei belassen. Er hält sich wenn möglich für sich, haust meist unter dem Blätterdach und zieht von einem spärlich bewohnten Ort zum nächsten."]],
 praesenz:{sicht:"Eine felsige Insel, durchzogen von seltsam regelmäßigen Höhleneingängen. Eine sich bewegende Steinmasse, die einem weitmäuligen Vogel gleicht. Dampf- oder Nebelstöße aus leeren Augenhöhlen. Ein Steinschnabel, zehnmal so groß wie ein durchschnittliches Schiff.", klang:"Das Mahlen von Stein auf Stein. Zischen entweichenden Dampfs. Vielleicht eine kleine Stimme aus tiefem Inneren …?", geschmack:"Splitter der Potoo-Haut schmecken … nun ja, nach Stein. Was hast du erwartet?"},
 ressourcen:{bergegut:["Steinsplitter","Zerschmetterter Motor","Uraltes Rohrwerk","Wrackfragmente"], proben:["Knochen eines Entdeckers","Splitter einer Steinseele"], gefluester:["Kein Stein ungewendet","Ihren Geräten überlassen","Silikatseele","Nicht der klügste Zug"], fracht:["Brocken lebenden Steins","Intakter Motor","Ruinierte Genesis-Technologie"]},
 aspekte:[["Lebende Insel","Als wahrer Leviathan (auch wenn künstlich erschaffen) verringert der Monument Potoo die Wucht von Schaden gegen ihn und behandelt eingehenden massiven Schaden als normalen Schaden. Außerdem ist die Steinhaut des Geschöpfs äußerst widerstandsfähig und ignoriert jeden Schaden außer Stumpf und Explosion völlig. Das Innere des Geschöpfs anzugreifen oder einen Teil des Außensteins abzubrechen, hebt diese zusätzliche Einschränkung wirksamer Schadensarten auf."],["Es war einmal eine Insel","Und vielleicht ist es das noch. Solange er sich bewegt, ist die Vogelgestalt des Potoo deutlich erkennbar, doch in Ruhe würden die meisten den Leviathan für eine steinige Landzunge halten (die allerdings seltsam frei von Bewuchs und Besiedlung ist)."],["Abwehrmaßnahmen","Der Monument Potoo ist kein komplexer Kämpfer – er packt und zerschmettert Schiffe mit seinem Schnabel, wenn sie nah genug kommen, und verursacht massiven NK-Stumpf-Schaden. Tatsächlich flieht er eher vor sich nähernden Gefährten, als zu bleiben und zu kämpfen, und wendet sich nur gegen die hartnäckigsten Verfolger."],["Innere Abläufe","Die Ingenieure und Steinmetze, die an der Erschaffung des Potoo arbeiteten, bauten ihre Häuser und Werkstätten in Höhlen in dem, was schließlich das Geschöpf werden sollte. Obwohl diese Höhlen nun als der weitläufige Magen des Potoo dienen und die Bewegung des Leviathans viele dieser Strukturen in Stücke gerissen hat, gibt es noch viele wertvolle arconautische und technologische Artefakte in ihren Ruinen. Crews sollten sich bewusst sein, dass das Innere des Monument Potoo stockfinster ist, außer an den Stellen, die durch das durch die leeren Augenhöhlen des Geschöpfs einfallende Licht erhellt werden."]]},
{id:"that-feral-roa", t:"That Feral Roa", en:"That Feral Roa", kat:"leviathane", p:180, q:"sr", groesse:"Protoleviathan", unter:"Schrecken der unteren Himmel",
 x:"Manche leviathanartigen Wesen erwerben ihren Ruhm durch schiere Größe oder durch die Seltsamkeiten, die ihre Anwesenheit bringt. Nicht so That Feral Roa – kaum groß genug, um überhaupt als Protoleviathan zu gelten, ist die Bestie dennoch zur zentralen Figur einer riesigen Menge von Geschichten, Liedern und Gedichten geworden, die sich mit den Gefahren des Luftreisens befassen. Warum? Weil das Geschöpf Schiffe nicht zur Nahrung jagt, sondern zum Vergnügen – es ist ein Geschöpf mit echter Grausamkeit, dessen wahnsinnige, rollende Augen nur Fokus und Absicht zu gewinnen scheinen, wenn es Beute im Visier hat.\nThat Feral Roa findet man meist, wie es von Ast zu Ast über das Blätterdach der Wildsee springt, doch mehr als eine Crew hat ihr Leben verloren, weil sie dachte, es sei durch seine Größe beschränkt; obwohl Fliegen ihm schwerfällt, treibt die Aussicht, ein mögliches Ziel nicht zu erlegen, es in eine wilde Spirale aus Flattern und Kreischen, die es kurz, aber explosiv in die unteren Himmel schrauben lässt, um Schiffe zu schnappen, die auf die Sicherheit der Wolken zuhalten. Setze That Feral Roa ein, wenn die Crew einem Leviathan gegenüberstehen soll, der klein genug ist, dass sie ihn vielleicht ohne Vorbereitung abwehren kann, der sie aber hartnäckig über die Wellen jagen wird, bis er endgültig erledigt ist.",
 erzaehl:"„Es kommt noch immer, Sir!“\nDer Kapitän fluchte und fegte mit einer Bewegung seines Kaktoid-Arms den Stapel Seekarten neben sich davon. Der Ausguck, der gerufen hatte, zuckte bei der Bewegung zusammen, blieb aber fest auf seinem Posten – sie waren nun seit zwei Tagen wach und in Bewegung, und die Bestie schien nicht näher daran, zu ermüden, als zu Beginn.\nAber ihr Schiff? Das war eine andere Geschichte. Sie hatten so viel versucht, um zu entkommen – waren in die Luft gegangen, nur um die Gashüllen von einem Hagel aus Klauen zerfetzen zu lassen, hatten so viel Tempo aus ihren Motoren herausgeholt, wie sie konnten, bis das gesamte Unterdeck wegen gefährlichen chemischen Abgases evakuiert werden musste. Sogar unter das Geflecht waren sie abgetaucht, so unvorbereitet, wie sie waren, nur um zu begreifen, dass es der Bestie nur erlaubte, Boden gutzumachen.\nEs war ein Wettlauf zum Hafen, und sie waren noch einen Tag entfernt. Er versprach, ein langer zu werden. Oder, im schlimmsten Fall, ein sehr kurzer.",
 antriebe:[["Zielstrebige Wut","Was hat That Feral Roa in einen so wütenden Zustand getrieben? Es ist zu irre, um zu schlafen, zu ruhen, getrieben von purem Hass auf alles, was es wagt, sein Revier zu betreten. Und sein Revier ist, soweit jemand erkennen kann, überall, wo es hinsehen kann."]],
 praesenz:{sicht:"Ein Vogel von der Größe eines Schlachtschiffs, der auf ein kleineres Gefährt herabstößt. Augen voller Verlangen nach nichts als Zerstörung. Furchen in Siedlungsmauern und zertrümmerte Stege an beunruhigend leeren Häfen.", geruch:"Blut, Moschus, Schweiß, Wut."},
 ressourcen:{proben:["Roa-Feder","Verworfene Überreste"], gefluester:["Zum Wahnsinn getrieben","Morast und Federn"]},
 aspekte:[["Geflügelter Protoleviathan","Da ihnen Größe und Verteidigung eines wahren Leviathans fehlen, verringern Protoleviathane die Wucht allen Schadens, den sie erleiden würden, können aber noch immer mit herkömmlichen Waffen und klugen Taktiken verletzt oder zurückgeschlagen werden. Einen zu erlegen, ist dennoch eine nahezu unmögliche Aufgabe. That Feral Roa kann auch fliegen, wenn auch nur tief über den Baumwipfeln; er nutzt eher einen federnstreuenden Sprung als einen kontrollierten Gleitflug, um irgendein Hindernis oder eine Lücke zu überwinden."],["Wütende Klauen, kreischender Schnabel","That Feral Roa ist ein geradliniger Angreifer, der mit den Klauen schlitzt und mit dem Schnabel aufspießt und zuschnappt. Er verursacht mit den meisten Angriffen massiven NK-Scharf- oder Hieb-Schaden, doch Wildsegler, die ihn zu nah herankommen lassen, werden wahrscheinlich vorübergehend von einem Kreischen betäubt, das stark genug ist, FK-Explosions-Schaden zu verursachen."],["Zielstrebige Verfolgung","Hat That Feral Roa ein Schiff im Visier, erfordert es gewaltige Anstrengung, ihn abzulenken oder von der Jagd abzubringen. Fängt er seine Beute, reißt er sie auseinander, bis nichts als Scherben und Splitter übrig sind, verzehrt alles Lebendige und zerstört alles Nichtorganische gründlich."],["Feuer vom Himmel","Die Ausnahme bilden Stürme und offene Flammen, die beide die Bestie zurücktreiben (zumindest eine Weile). Man vermutet, dass dies einer der Gründe ist, warum das Geschöpf es unterlässt, selbst in der Luft nahe an Wolken zu fliegen, vielleicht aus Furcht vor Blitzen oder verborgenem Feuer. Aus welchem Grund auch immer, diese angeborenen Ängste sind einige der wenigen Vorteile, die eine Crew über das Geschöpf erlangen kann, und jeder birgt bereits seine eigenen Risiken."]],
 eigenheiten:[{t:"Dosenfutter",x:"Hin und wieder versucht That Feral Roa, eine Siedlung statt eines Schiffs anzugreifen, reißt die Dächer von Behausungen ab und pickt die schreienden Happen darin heraus. In solchen Situationen reichen die vereinten Bemühungen der Bevölkerung normalerweise aus, ihn zurückzuschlagen, doch sie müssten der Bestie irgendeine schwere Verletzung zufügen, um sie lange fernzuhalten."},{t:"Und schließlich Schlaf",x:"Der Roa schläft – es ist ein unruhiger Schlaf, kaum leiser oder ruhiger, als wenn er wach ist, aber es ist dennoch Schlaf. Was dieses unglaublich seltene Phänomen auslöst, wer kann das sagen?"}]},
{id:"isoma", t:"Isoma", en:"ISOMA", kat:"leviathane", p:182, q:"sr", groesse:"Leviathan", unter:"Träumend von einem lange verlorenen Meer",
 x:"Ein blassschaliger Isopode von der Größe einer Stadt, der endlos und ziellos durch die pechschwarzen Räume zwischen den dicksten Ästen der Eisenwurzeln kriecht. Doch anders als bei den meisten Leviathanen ist das störendste Element von Isomas Reise nicht das Geschöpf selbst (so groß es auch ist), sondern der Traum, den es ausstrahlt. Ein alter Traum, ein gefangener Traum, ein komplexer Traum, der nie ihm gehören könnte – der Traum eines Seglers der uralten Meere vor den Ästen, der Zeit vor der Verdancy, eines Ozeans, in dem Wellchen und Kräuselungen die Sonne einfangen und Vögel um Fischstücke kämpfen, die Kinder am Strand werfen.\nEs ist zunächst ein angenehmer Traum – doch wie bei den meisten Träumen lauern unter der Oberfläche Dinge, die jene bedrohen, die verweilen. Erinnerungen daran, wie es ist, unter die Wellen zu gleiten, oder an Ankerseil, das sich um ein ahnungsloses Glied gewickelt hat, oder daran, nach einer Liebsten zu rufen, die einen nicht hören kann, während sie zum letzten Mal den Horizont überquert. Und, stärker als alles andere, Wasser – Wasser unten, oben, ringsum, und eine köstliche Freiheit und erdrückender Druck in einem.\nIsoma trägt diesen Traum mit sich, spielt ihn in tausend Variationen ab. Und die, die ihm nahekommen, spielen ihre Rollen, wenn sie unvorbereitet erwischt werden, oder kämpfen darum, in der Wirklichkeit zu bleiben, wenn sie entschlossen genug sind, es zu versuchen. Setze Isoma ein, wenn die Crew etwas erleben soll, das in der Wildnis sonst fehlt – weite Salzwasser-Ozeane, die Fähigkeit zu schwimmen und, vielleicht am wichtigsten, einen Blick auf die vorverdante Welt – oder zumindest eine Version davon, aus einem winzigen Küstenfischerdorf, das vielleicht nie existiert hat.",
 erzaehl:"Du wachst vom Lärm der Möwen in der Luft auf, von Wellen, die an ein steiniges Ufer plätschern, die Sonne tüpfelt die Gestalt deines Mannes, der neben dir schläft. Deine Decken sind mit Wolken bestickt, und das Treibholz über dem Kamin wirft einen vertrauten Schatten.\nNein.\nDas ist falsch.\nIn der Speisekammer liegt Speck, und bald wird es ein Morgen aus heißem Fett und frischer Butter und einweichenden Pfannen sein. Das Brot aus dem nächsten Dorf ist ein wenig zu teuer für deinen Geschmack, aber nichts geht über den Geruch frisch aus dem Ofen oder den Geschmack.\nNein.\nDu zappelst wild und ringst nach Luft.\nDas ist …\nIn gewisser Weise entspannend. Du musst erst gegen Mittag zu den Docks. Reichlich Zeit, die Wärme von Bett und Partner zu genießen, beide vertraut, beide verlässlich.\nKeiner von beiden gehört dir.\nDu ertrinkst, doppelt.",
 antriebe:[["Warten, bis die Welt sich wieder dreht","Manche glauben an Kreisläufe, dass eines Tages die Wildnis fortgespült wird und Salz und Wasser und wahre Gezeiten zurückkehren. Vielleicht glaubt Isoma das auch. Vielleicht glaubt es nichts. Vielleicht hat es verlernt, wie, oder es nie für nötig gehalten."]],
 ressourcen:{proben:["Schalenfragmente","Ozeanischer Bernstein"], gefluester:["Das alte Salzmeer","Ertrinken in Erinnerung"], fracht:["Eingebernsteinter Traumbrocken"]},
 aspekte:[["Blasse Schale","Als wahrer Leviathan behandelt Isoma eingehenden massiven Schaden als normalen Schaden. Außerdem ist es völlig immun gegen Flammen- und Stumpf-Schaden, unabhängig von der Wucht, es sei denn, du befindest dich in seiner Schale oder hast sie irgendwie entfernt."],["Die Vergangenheit hinter sich herziehen","Isoma kümmert sich nicht genug um die meisten Gefährte, um sie anzugreifen – oder um irgendetwas in der Wildnis um es herum, wenn man so will. Die wahre Gefahr des Geschöpfs, abgesehen von der gewaltigen Größe (da es massiven NK-Stumpf-Schaden an Schiffen und Siedlungen verursachen kann, indem es einfach über oder durch sie kriecht), ist die halbmeilenbreite Aura greifbaren Traums, die es mit sich schleift. Objekte und Individuen in dieser Aura verhalten sich, als wären sie unter Wasser, wobei die Wirkung umso stärker wird, je näher man Isoma kommt. Beachte, dass es kein Wasser gibt – es ist ein rein gemeinsamer Traum. Aber ein Traum, der stark genug ist, dass du innerhalb einiger Steinwürfe vom Geschöpf wirksamer durch die Luft schwimmen als gehen könntest."],["Ein Traum vom Ertrinken","Zu tief in den Traum zu fallen, kann deinen Körper überzeugen, völlig untergetaucht zu sein – oder bist du wirklich untergetaucht, und das Wasser selbst ist anderswo? Wie auch immer die Wahrheit aussieht, Tatsache ist, dass die Erfahrung sowohl schmerzhaft als auch von Natur aus morastträchtig ist – mittlerer bis schwerer Salz-Schaden ist angemessen, ebenso bleibende Verletzungen, und Morast ist bei einer solchen Erfahrung fast unvermeidlich."]],
 eigenheiten:[{t:"Eine flüchtige Chance",x:"Manchmal hält Isoma inne, ruht und behält den Traum für sich. In diesen Phasen, meist nur eine oder zwei Stunden und unmöglich vorherzusagen, könnte ein Angriff auf das Geschöpf möglich sein."}],
 extra:[["Präsenz – Traum","Salz. Wasser. Freundschaft. Verlust. Liebe. Tiefe."]]},
{id:"pearlskull", t:"Pearlskull", en:"Pearlskull", kat:"leviathane", p:183, q:"sr", groesse:"Protoleviathan", unter:"Ein Fluch der Ketra-Gemeinschaft",
 x:"Angesichts der gallertartigen, treibholzknochigen Natur des durchschnittlichen Ketra ist es leicht zu vergessen, dass sie ihre Existenz demselben uralten menschlichen Stamm verdanken wie die Ardent. Nur dank der Tiefen, in denen sie sich entwickelten, traten ihre säugetierhaften Aspekte zurück, ersetzt durch andere, besser geeignete Anpassungen. Und für die meisten Ketra ist diese Abstammung aus der alten Welt kaum mehr als eine Fußnote in ihrem Ahnengedächtnis, eine Kuriosität, über die man nachsinnt, während man Stunden an einem Wachposten oder einer Hafenkreuzung zwischen Reisen vertrödelt.\nAber für die Pearlskulls war es eine Aberration.\nDie Ketra-Gemeinschaft Pearlskull ist vielleicht die tiefste je verzeichnete überlebende Siedlung, eine ozeanische vorverdante Forschungsstation mit einem längst vergessenen Zweck. Sie wurde von der Verdancy erfasst, vom Wachstum der entstehenden Wellen nach oben getragen und prekär zwischen den untersten Ästen der Tiefe abgesetzt. Die Überlebenden stellten innerhalb von Monaten fest, dass sie sich veränderten, dank der crezzerin-durchtränkten Luft, die noch durch die Umgebung wogte, jeder Atemzug ein Gleiten in eine herrliche knochenlose Existenz. Und anders als die Mehrheit der angehenden Ketra, die solche Veränderungen so gut sie konnten hinnahmen, machten sich die Forscher von Pearlskull daran, den Prozess so gut es ging zu beschleunigen – die Welt hatte sich verändert, und sie waren entschlossen, sich mit ihr zu verändern.\nDie Ergebnisse ihrer Bemühungen sind offenkundig, wann immer der Protoleviathan Pearlskull seine tropfende Masse zur Jagd in der Senke emporhievt. Ein einziger Organismus, etwas, das großzügig noch als ketra-ähnlich bezeichnet werden könnte, aber in gewaltigem Maßstab. Die gesamte Biomasse der Forschungsstation vereint, ein protoplasmatisches Grauen aus lebender Flüssigkeit und leuchtenden Mustern.\nUnd wenn man Gerüchten und müßigem Klatsch glauben darf …\nEs erinnert sich, wie es war, Mensch zu sein.\nSetze Pearlskull ein, wenn du ein lebendes Denkmal der Torheit willst, eine intelligente, von ihren Umständen in den Wahnsinn getriebene Bedrohung mit vorhandenen, aber unbekannten Absichten.",
 antriebe:[["Kryptisch und unkommuniziert","Pearlskull jagt, aber er sammelt auch. Er fängt Tauchboote samt Crew in das Gewebe seiner eigenen Gestalt ein, aber nicht als Nahrungsquelle oder als Akt sinnloser Aggression. Tatsächlich achtet er sorgfältig darauf, die Schiffe, die er fängt, nicht zu beschädigen. Dort unten in seinem Zuhause geschieht etwas, aber ihm fehlen die Fähigkeit und die Neigung, es jemand anderem mitzuteilen."]],
 praesenz:{sicht:"Ein Leuchten aus der Tiefe unter den Wellen. Schleim, der von Ästen tropft. Eine riesige, menschenähnliche Gestalt, die sich aus der Dunkelheit aufbäumt.", klang:"Verzerrtes Heulen, das fast als Chthonisch erkennbar sein könnte. Das Zerschmettern und Biegen von Ästen.", geruch:"Überhaupt keiner, eine merkwürdige Abwesenheit."},
 ressourcen:{bergegut:["Verdrehte Hölzer","Vorverdanter Tand"], proben:["Ketratisches Plasma","Leuchtende Flüssigkeit"], gefluester:["Von Ehrgeiz verflucht","Ein Rückzug von Knochen"]},
 aspekte:[["Eisenwurzel-Skelett","Als wahrer Leviathan behandelt Pearlskull eingehenden massiven Schaden als normalen Schaden. Wie die meisten von Ketra abgeleiteten Organismen braucht er auch ein Skelett irgendeiner Art zur Fortbewegung – wegen der Größe des Geschöpfs splittert und gliedert es Eisenwurzel-Äste (und gelegentlich Stämme) wie ein inneres Gerüst in sich ein. Pearlskull ist schwach gegen Flammen- und Stich-Schaden, aber das war es auch schon."],["Lichter im Schädel","Die leuchtenden Flecken des Pearlskull wandern und laufen über seinen Körper, während er sich bewegt, und bleiben nie lange an einem Ort. Sie erhellen seine Umgebung, können aber weit mehr, wenn das Geschöpf sich bedroht fühlt – indem es die leuchtenden Bereiche seiner selbst zu einem Anhängsel bündelt, beginnt der Protoleviathan, einen Verzerrungseffekt auszustrahlen, der Haut so sicher versengt wie Crezzerin. Das verursacht FK-Flammen-Schaden über ein großes Gebiet, lässt aber betroffene Objekte und Individuen welken und verdorren, statt sie in Brand zu setzen."],["Einst wie wir","Pearlskull ist eine lebende Warnung vor der Gefahr des Verlangens – wann immer er ein Ziel dazu bringt, Morast zu markieren, verbrennt das Ziel stattdessen ein Kästchen Morast."]],
 extra:[["Pearlskull Actual (Ort)","Worte, über der Ladebucht von einem unglücklichen Entkommenen gemalt: GRAB. SCHOSS. Habitat-Kapseln: Drei verbleibend. Obwohl der kleine Komplex von Pearlskull Actual während der Verdancy die meisten seiner ursprünglichen Räume verlor, sind die verbleibenden Bereiche ein Schrein der Technologie der alten Welt und vorverdanter historischer Daten. Der Zugang zu diesen Informationen ist dank Pearlskull selbst fast unmöglich, der im gesamten Komplex dahinsiecht, wenn er nicht jagt oder fängt (sein plasmatischer Körper füllt fast jeden verfügbaren Raum)."],["Die Bucht der Knochen (Merkmal)","Ein aufgebrochener Frachtlagerbereich, wie es aussieht. Die Bucht der Knochen ist funktional benannt, der einzige Raum in Pearlskull Actual, der groß genug ist, um das Eisenwurzel-Skelett aufzunehmen, in das er schlüpft, wenn er die Wellen erkunden muss. Die Bucht der Knochen ist der einzige Weg in die Forschungsstation, ohne sich durch sehr hochwertige Druckdichtungen zu schneiden."],["Das Experiment (Grauen)","Pearlskull entführt Schiffe und Crews nicht einfach zum Vergnügen. Im innersten Heiligtum seines Heims läuft ein Experiment, das seit Jahren ergebnislos läuft. Aber … vielleicht sind sie einem Durchbruch nahe. Nein, wir werden dir nicht sagen, was sie zu erreichen versuchen. Aber was immer es ist, es ist nicht angenehm."]]},
{id:"the-howl-eternal", t:"The Howl Eternal, a Beast of Strangled Words", en:"The Howl Eternal, a Beast of Strangled Words", kat:"leviathane", p:184, q:"sr", groesse:"Leviathan", unter:"Ein tausendfaches Flüstern bestialischer Wut",
 x:"Eine Crew hört es vielleicht zunächst in der Ferne, getragen vom wechselnden Wind, wenn sie eine Welle erklimmt oder in einer Nacht Wache hält. Ein Tierschrei, unmöglich zu bestimmen, der den Hörer an eine von Einsamkeit oder Schmerz oder Wut wahnsinnig gewordene Bestie erinnert. Ihn zu hören, selbst aus der Ferne, genügt, um allen außer den erfahrensten Leviathaneers einen Schauer über den Rücken zu jagen.\nUnd ihn jagen?\nDie meisten Crews knicken ein, noch bevor sie die Bestie zu Gesicht bekommen, und wenden ihre Schiffe angesichts einer Lärmwand, die nur an Intensität und Komplexität zuzunehmen scheint. Wenn Crews nah genug sind, dass Lungen zittern und Ohren bluten, werden sie die Wahrheit des Klangs begreifen: dass es nicht ein einzelnes bestialisches Maul ist, sondern eine unmögliche Anzahl, und dass das Heulen ein verdrehter Trauergesang aus Worten ist, die sie von Zeit zu Zeit sogar verstehen können. Was für eine Bestie könnte einen so kakofonischen, ständigen Schrei hervorbringen?\nÜberhaupt keine Bestie, entdecken jene, die ihr am nächsten kommen, sondern die Flüstern einer zur Wirklichkeit gewordenen Bestie. Massen zottigen Haars in Farbe und Beschaffenheit von Mondlicht, gebleckte, halbsubstanzielle Zähne, Fleisch wie eine entblößte Seele – das Howl Eternal ist ein Wirbelsturm verhedderter Flüstern, zu Gestalt gewordene Worte der Wut. Setze The Howl Eternal ein, wenn die Crew etwas Gewaltiges, Wutgefülltes bekämpfen soll, das alles um sich herum wahllos zerstört und ein sich ständig wandelndes Einsatzfeld schafft, das am besten von Schiffen angegangen wird, die im Handumdrehen unter die Wellen abtauchen oder in die Luft aufsteigen können.",
 erzaehl:"Es gibt Worte im Wind. Keine grausamen Worte, aber auch keine freundlichen. Sie ergießen sich ohne Zustimmung, ohne den Wunsch, etwas anderes zu sein als gehört, aber selbst dann machen sie das Zuhören zu einer solchen Herausforderung. Warum sendet man aus, was Verstand verwirrt und Träume kreuzt, wenn nicht als Herausforderung? Warum die Prüfung der Welt mit endlosem Klang und Sinn einladen?\nMeine Crewkameraden schreien mich an, die Hände auf das gepresst, was bei ihnen als Ohren durchgeht. Sie hören nicht dasselbe wie ich, das ist offensichtlich, oder wenn doch, können sie es nicht so verstehen wie ich. Sie kommen schneller, ein silbenhafter Sturm, ein Unwetter aus Plosiven und hässlichen, zerbrochenen Phrasen. Ich habe hunderttausend Körper, aber ich werde von der Wucht erschüttert, und mit jedem Augenblick wickelt sich ein neuer Bedeutungsfaden ab.\nEs ist mehr als ein Heulen, schreie ich, und die Worte werden fortgerissen, um sich ihren Gefährten anzuschließen. Du wirst es bald auch hören.",
 antriebe:[["Den Lärm verbreiten","The Howl Eternal hat keine erkennbaren eigenen Ziele, außer zu taumeln und zu schreien und gegen die Welt zu wüten. Ganze Siedlungen räumen sich beim ersten Anzeichen seines Nahens und kehren Tage später zu zerbrochenen Fenstern und einer unheimlichen, zu lauten Stille zurück."],["Wer sprach zuerst?","Obwohl in der Brust des Howl Eternal ein Geheimnis liegt, ist der Einzige, der ihm je nahegekommen ist, einer, der verschluckt wurde … Und die unglücklichen Wenigen kehren selten zurück, um ihre Erkenntnisse preiszugeben. Falls je jemand es täte, könnte er Geschichten erzählen von einer menschenähnlichen Gestalt, durch die Größe der Bestie mikroskopisch klein gemacht, fötal zusammengerollt im Flüsterfleisch ihrer Brust."]],
 praesenz:{sicht:"Ein Exodus von Schiffen, deren Segler und Passagiere Wachsstöpsel in den Ohren tragen (sofern sie Ohren haben, in die sie sie stecken können). Ein fernes Leuchten, wie Mondlicht. Schneisen durch das Gestrüpp, zerstörte Inseln und an der Krone abgeknickte Eisenwurzeln. Wilde Büschel silbrigen Haars, die Worte abwerfen, während sie sich bewegen.", klang:"Eine ohrenbetäubende Kakofonie, laut genug, um Stein zu zerschmettern.", geschmack:"Wie Worte, die du schreien willst, aber nie konntest."},
 ressourcen:{proben:["Flüsterfleisch","Mondlicht-Fell"], gefluester:["Heul, Heul, Heul, Heul, Heul …"], fracht:["Wort-beschriebener Zahn","Zerbrochener Inselstein"]},
 aspekte:[["Eine Haut aus Worten","Wie die meisten Leviathane verringert das Howl Eternal die Wucht von Schaden gegen es und behandelt eingehenden massiven Schaden als normalen Schaden. Anders als die meisten Leviathane hat das Howl eine zusätzliche Verteidigung – seine Haut, sein Fleisch und sein Haar bestehen aus lebenden Flüstern, ständig im Wandel und nur teilweise profan. Um der Bestie bleibenden Schaden zuzufügen, müssen Crews sie in Verbindung mit ihren Angriffen mit eigenen Flüstern treffen, oder alle Wunden, die sie doch zufügen, schließen sich binnen Augenblicken wieder."],["Der Lärm","Den ständigen Schrei des Howl aus der Ferne zu hören, markiert Morast, doch je näher die Crews der Bestie kommen, desto stärker spüren sie die körperlichen Wirkungen. Eigenschaften, Ausrüstung und Gefährten werden von zunehmenden Intensitäten FK-Explosions-Schaden betroffen, je länger sie in der Nähe des Geschöpfs bleiben, und wenn sie nah genug sind, beginnen auch die Werte ihres Schiffs zu schwinden."]],
 eigenheiten:[{t:"Einfach zu viel",x:"Dem Tier nah genug zu kommen, um irgendeine Art von Angriff zu starten, macht es der Crew unmöglich, irgendetwas anderes als das Geschöpf selbst zu hören. Ohrenschutz ist nötig, um zu widerstehen, statt wegen der Intensität des Lärms Verbrennen zu erleiden und nicht bloß Markierungen."},{t:"Das Auge des Sturms",x:"Es ins Innere des Howl Eternal zu schaffen, bringt ein seliges Gefühl von Frieden, der Lärm noch hörbar, aber von der flüsternden Haut des Geschöpfs gedämpft."}]}
);
